+		t.Error("esc did not close the composer")
+	}
+	if len(src.comments) != 0 {
+		t.Errorf("esc sent %d comments", len(src.comments))
+	}
+	if strings.Contains(ansi.Strip(m.View()), "never mind") {
+		t.Error("the discarded draft is still on screen")
+	}
+}
+
